const records=[];
function add(id,title,answer,solution,lines){records.push({id:'OGEPHYS'+id,title,answer,solution,lines,diagram:'',richLabels:true});}
const hydro=`Рассматриваем покоящуюся жидкость в системе отсчёта Земли. Глубину h отсчитываем вниз от свободной поверхности. На выделенный вертикальный столб жидкости действуют его тяжесть вниз и силы давления на верхнюю и нижнюю грани. Из равновесия по вертикали следует:
p_низ · S − p_верх · S − ρgSh = 0;
p_низ = p_верх + ρgh.
Поэтому избыточное давление воды на глубине h равно p = ρgh, а сила её давления на горизонтальное дно площади S равна F = ρghS. Атмосферное давление на открытой поверхности одинаково в сравниваемых состояниях.`;
const suspension=`Система отсчёта связана с Землёй, ось Oy направлена вверх. На груз действуют сила тяжести mg вниз, сила упругости пружины F_упр вверх и выталкивающая сила F_А вверх. Медленное движение считаем равномерным; сопротивлением воды пренебрегаем. Второй закон Ньютона в проекции:
F_упр + F_А − mg = 0.
По закону Архимеда:
F_А = ρ_в · gV_погр.
Следовательно:
F_упр = mg − ρ_в · gV_погр.
Здесь V_погр — только объём части груза, находящейся под водой; массу самого груза погружение не меняет.`;
for(const [id,heating] of [['7EF04B',true],['2B5636',false]]){
 const answer=heating?'31':'32',verb=heating?'нагревают':'охлаждают';
 add(id,heating?'Нагревание газа в закрытом сосуде':'Охлаждение газа в закрытом сосуде',answer,`Газ ${verb} в закрытом сосуде с жёсткими стенками. В принятой модели сосуд не деформируется, газ не выходит и не поступает извне. Его объём равен постоянному внутреннему объёму сосуда, поэтому для объёма выбираем цифру 3.
Работаем в системе сосуда. Давление создаётся ударами молекул о стенки: при ${heating?'нагревании средняя скорость молекул возрастает, удары становятся интенсивнее':'охлаждении средняя скорость молекул уменьшается, удары становятся менее интенсивными'}. Поэтому давление ${heating?'увеличивается — цифра 1':'уменьшается — цифра 2'}.
Для количественного описания той же модели постоянной массы газа можно записать:
⟦p₂¦p₁⟧ = ⟦T₂¦T₁⟧ при V = const,
где T — абсолютная температура в кельвинах. Использовать отношение температур в градусах Цельсия здесь нельзя.
Проверка: ${heating?'T₂ > T₁, значит p₂ > p₁':'T₂ < T₁, значит p₂ < p₁'}, а объём остаётся прежним. В порядке «объём, давление» ответ: ${answer}.`,['Жёсткий закрытый сосуд: V = const','Масса и число молекул сохраняются',heating?'Температура растёт → давление растёт':'Температура падает → давление падает','Ответ: '+answer]);
}
for(const [id,down,first,second,ans] of [['6E081F',true,'давление','объём','12'],['ABB0C2',false,'давление','средняя скорость молекул','23'],['F1FE9E',false,'давление','плотность','22'],['B70F92',true,'плотность','средняя скорость молекул','13']]){
 add(id,'Газ под поршнем при постоянной температуре',ans,`Герметичный поршень перемещают ${down?'вниз':'вверх'}, поэтому объём газа ${down?'уменьшается':'увеличивается'}. Масса m и число молекул сохраняются, температура постоянна. Рассматриваем последовательность равновесных состояний в системе цилиндра.
При одинаковой температуре средняя скорость теплового движения молекул не меняется. Изменяется число молекул в единице объёма, а вместе с ним частота ударов о единицу площади стенки. При ${down?'сжатии концентрация и давление растут':'расширении концентрация и давление уменьшаются'}.
Плотность определяется формулой:
ρ = ⟦m¦V⟧.
Для одной и той же массы газа при постоянной температуре:
p₁V₁ = p₂V₂;
⟦p₂¦p₁⟧ = ⟦V₁¦V₂⟧;
⟦ρ₂¦ρ₁⟧ = ⟦V₁¦V₂⟧.
Таким образом, ${first} ${ans[0]==='1'?'увеличивается':'уменьшается'} — цифра ${ans[0]}; ${second} ${ans[1]==='3'?'не изменяется':ans[1]==='2'?'уменьшается':'увеличивается'} — цифра ${ans[1]}.
Проверка: если объём ${down?'уменьшить':'увеличить'} вдвое при той же температуре, плотность и давление ${down?'возрастут':'уменьшатся'} вдвое, а средняя скорость молекул останется прежней. Ответ: ${ans}.`,[down?'Поршень вниз → объём уменьшается':'Поршень вверх → объём увеличивается','T = const; m = const','p₁V₁ = p₂V₂; ρV = m','Ответ: '+ans]);
}
for(const [id,n1,n2,ans] of [['E07548',6,4,'1,5'],['50D772',6,2,'3']])add(id,'Плотности несмешивающихся жидкостей',ans,`На рисунке жидкость 1 образует отдельный столб слева, жидкость 2 заполняет нижнюю часть трубки и правое колено. Высоты нужно отсчитывать от горизонтальной границы жидкостей слева, а не от самого дна U-образного сосуда.
${hydro}
На уровне границы в соединённой жидкости 2 давления одинаковы. Обе свободные поверхности открыты воздуху:
p_атм + ρ₁gh₁ = p_атм + ρ₂gh₂;
ρ₁h₁ = ρ₂h₂.
Искомое число, показывающее, во сколько раз первая плотность меньше второй:
⟦ρ₂¦ρ₁⟧ = ⟦h₁¦h₂⟧.
По исходной линейке высота первого столба занимает ${n1} одинаковых крупных интервалов, второго — ${n2}. Если длина одного такого интервала a, то:
⟦ρ₂¦ρ₁⟧ = ⟦${n1}a¦${n2}a⟧ = ${ans}.
Проверка: ρ₂gh₂ = ${ans}ρ₁ · g · ${n2}a = ${n1}ρ₁ga, что равно давлению первого столба. Ответ: в ${ans} раза.`,['Высоты считаем от границы жидкостей','ρ₁gh₁ = ρ₂gh₂',`h₁ : h₂ = ${n1} : ${n2}`,'Ответ: '+ans]);
for(const id of ['364F4E','C0D0C6'])add(id,'Показание барометра и погрешность','2',`На фотографии барометра нанесены две шкалы. Для ответа в миллиметрах ртутного столба читаем именно шкалу с обозначением «мм рт. ст.», а не соседнюю шкалу давления в других единицах.
Между подписанными отметками 750 и 760 находятся десять равных промежутков. Цена деления:
c = ⟦p_вторая − p_первая¦n⟧.
Подстановка:
c = ⟦760 − 750¦10⟧ мм рт. ст. = 1 мм рт. ст.
Стрелка стоит посередине между 750 и 760, то есть на отметке 755 мм рт. ст. По условию абсолютная погрешность равна одной цене деления, поэтому Δp = 1 мм рт. ст.
Результат измерения записываем вместе с единицей:
p = (755 ± 1) мм рт. ст.
Это вариант 2. Значение около 100,7 относится к килопаскалям другой шкалы; его нельзя записать как 100,7 Па или как 100,7 мм рт. ст.
Проверка: интервал измерения от 754 до 756 мм рт. ст. охватывает показание стрелки; его полуширина совпадает с заданной погрешностью. Ответ: 2.`,['Шкала: мм рт. ст.','10 промежутков между 750 и 760','Показание: 755; погрешность: ±1','Ответ: 2']);
for(const [id,enter,ans,conclusion] of [
 ['B0C9FC',true,'31','Сила тяжести груза не изменяется (3), сила давления воды на дно увеличивается (1).'],
 ['4D45B5',false,'12','Сила упругости увеличивается (1), сила Архимеда уменьшается (2).'],
 ['6DE9D1',false,'31','Сила тяжести не изменяется (3), сила упругости увеличивается (1).'],
 ['A31653',false,'22','Выталкивающая сила уменьшается (2), сила давления воды на дно уменьшается (2).']])add(id,enter?'Погружение груза на динамометре':'Выход груза из воды',ans,`${suspension}
Во время ${enter?'погружения':'выхода'} груза через поверхность воды V_погр ${enter?'возрастает':'уменьшается'}, следовательно, F_А ${enter?'увеличивается':'уменьшается'}, а F_упр ${enter?'уменьшается':'увеличивается'}. Когда груз целиком находится в воде, дальнейшее изменение только глубины не меняет силу Архимеда; здесь рассматривается именно изменение погружённой части.
Вода не выливается. Уровень воды в стакане при ${enter?'погружении повышается':'извлечении понижается'}. Площадь дна S и плотность воды постоянны, поэтому по формулам p = ρ_в · gh и F = pS сила давления воды на дно ${enter?'растёт':'уменьшается'}. Масса груза и g неизменны, значит mg постоянно.
${conclusion}
Проверка: вне воды F_А = 0, и динамометр показывает mg; при полном погружении он показывает mg − ρ_в · gV. Это согласуется с направлением изменения показания. В порядке столбцов ответ: ${ans}.`,['mg = const','F_упр + F_А = mg',enter?'V_погр растёт → F_А растёт':'V_погр уменьшается → F_А уменьшается',enter?'Уровень воды повышается':'Уровень воды понижается','Ответ: '+ans]);
for(const [id,toNarrow,ans] of [['43CC02',false,'22'],['46DBDE',true,'11']])add(id,'Переливание воды между сосудами',ans,`Воды в обоих состояниях 2 л, площади дна одинаковы. Один сосуд цилиндрический, другой сужается кверху. У сужающегося сосуда горизонтальные сечения выше дна меньше площади дна, поэтому для того же объёма воды требуется больший уровень, чем в цилиндрическом сосуде.
На исходном рисунке воду переливают ${toNarrow?'из цилиндрического сосуда 1 в сужающийся кверху сосуд 2':'из сужающегося кверху сосуда 1 в цилиндрический сосуд 2'}. Значит, h₂ ${toNarrow?'>':'<'} h₁.
${hydro}
При неизменных ρ, g и S получаем:
⟦p₂¦p₁⟧ = ⟦h₂¦h₁⟧;
⟦F₂¦F₁⟧ = ⟦h₂¦h₁⟧.
Поэтому давление и сила давления воды на дно ${toNarrow?'увеличиваются':'уменьшаются'}. Обеим величинам соответствует цифра ${ans[0]}.
Проверка: одинаковая масса воды означает одинаковую тяжесть, но не обязательно одинаковую силу давления на дно. Наклонные стенки также действуют на жидкость; в сужающемся кверху сосуде вертикальная составляющая этих сил направлена вниз и дополнительно нагружает дно. Ответ: ${ans}.`,[toNarrow?'Уровень воды повышается':'Уровень воды понижается','ρ, g, S не меняются','p = ρgh; F = pS','Ответ: '+ans]);
add('6A3406','Полное погружение плавающего кубика','31',`Вода не выливается из частично заполненного сосуда. Масса воды m_в и ускорение свободного падения постоянны, поэтому сила тяжести именно воды m_в · g не изменяется — цифра 3.
Работаем в системе Земли, Oy направляем вверх. Сначала на свободно плавающий кубик действуют mg вниз и сила Архимеда F_А вверх. Условие равновесия:
F_А − mg = 0;
ρ_в · gV_погр = mg.
Кубик плавает частично погружённым, значит V_погр меньше полного объёма V. Чтобы удерживать деревянный кубик под водой целиком, требуется дополнительная сила F вниз. Тогда:
F_А − mg − F = 0;
F = ρ_в · gV − mg > 0.
Полное погружение вытесняет больший объём воды; её свободная поверхность поднимается. Давление на дно p = ρ_в · gh увеличивается, а вместе с ним возрастает F_д = pS — цифра 1.
Проверка: рост силы на дно не требует увеличения массы воды. Дополнительная сила передаётся через удерживаемый кубик жидкости; при отпускании кубик всплывает и уровень возвращается к исходному. Ответ: 31.`,['Масса воды постоянна','Кубик удерживают силой F вниз','Полное погружение повышает уровень','Сила давления на дно растёт','Ответ: 31']);
for(const [id,max,ans] of [['6EE170',true,'2'],['B9A169',false,'4']])add(id,'Сравнение плотностей в сообщающихся сосудах',ans,`Все верхние поверхности открыты атмосфере, а границы дополнительных жидкостей с водой находятся на одной горизонтали. Рассматриваем равновесие в системе Земли. В соединённой покоящейся воде на этой горизонтали давление одинаково, иначе началось бы её перетекание.
Каждый верхний столб создаёт на границе давление:
p_i = p_атм + ρ_i · gh_i.
Поскольку p_i одинаковы, получаем:
ρ₁h₁ = ρ₂h₂ = ρ₃h₃ = ρ₄h₄.
Высоты h_i отсчитываются от пунктирной линии «уровень воды» до верхней поверхности соответствующей жидкости. Форма ветви сосуда не входит в это равенство.
Следовательно, плотность обратно пропорциональна высоте столба: ${max?'наибольшая плотность у самого низкого столба':'наименьшая плотность у самого высокого столба'}. На исходном рисунке это жидкость ${ans}.
Проверка: при одинаковом давлении вдвое более плотная жидкость должна образовать вдвое меньший по высоте столб. ${max?'Жидкость 2 имеет наименьшую высоту':'Жидкость 4 имеет наибольшую высоту'}, что согласуется с выбранной плотностью. Ответ: ${ans}.`,['Границы с водой — на одной горизонтали','ρ₁h₁ = ρ₂h₂ = ρ₃h₃ = ρ₄h₄',max?'Самый низкий столб — жидкость 2':'Самый высокий столб — жидкость 4','Ответ: '+ans]);
for(const [id,above,ans] of [['290412',false,'560'],['17215F',true,'960'],['12F090',false,'560']])add(id,'Давление газа по ртутному манометру',ans,`Газ подключён к правому колену, левое открыто в атмосферу. На исходной шкале указаны сантиметры. Уровень ртути со стороны газа ${above?'ниже':'выше'} уровня в открытом колене: значит, давление газа ${above?'больше':'меньше'} атмосферного.
Работаем в системе Земли. Из равновесия ртути следует: давления на одной горизонтали в соединённой жидкости равны. Разность давлений на её поверхностях равна давлению столба ртути высотой Δh:
|p_газ − p_атм| = ρ_рт · gΔh.
Вычислим разность уровней, не путая её с отдельным отсчётом:
Δh = 30 см − 10 см = 20 см = 200 мм.
Если давление уже выражено в миллиметрах ртутного столба, перепад составляет 200 мм рт. ст. Поэтому:
p_газ = p_атм ${above?'+':'−'} Δp.
Подстановка:
p_газ = 760 мм рт. ст. ${above?'+':'−'} 200 мм рт. ст. = ${ans} мм рт. ст.
Проверка: разность ${above?ans+' − 760':'760 − '+ans} равна 200 мм рт. ст.; большая сила давления действительно опускает ртуть на своей стороне. Ответ: ${ans}.`,[above?'Справа уровень ниже → давление газа больше':'Справа уровень выше → давление газа меньше','Δh = 30 − 10 = 20 см = 200 мм',`p_газ = 760 ${above?'+':'−'} 200 = ${ans} мм рт. ст.`,'Ответ: '+ans]);
for(const [id,above,ans] of [['48CFAC',false,'2357'],['34458E',true,'2457']])add(id,'Что измеряет U-образный манометр',ans,`U-образный манометр сравнивает давление газа с давлением воздуха у открытого колена. Сам по себе он показывает разность этих давлений, поэтому А — 2. Чтобы получить абсолютное давление газа, дополнительно нужно знать атмосферное.
Рассматриваем равновесие ртути в системе Земли. Давления на одной горизонтали в соединённой жидкости равны. Из этого следует:
|p_газ − p_атм| = ρ_рт · gΔh.
На рисунке уровень в правом колене, соединённом с газом, ${above?'ниже':'выше'} открытого. Поэтому давление газа ${above?'больше':'меньше'} атмосферного: Б — ${above?'4':'3'}.
Разность отсчётов:
Δh = 50 см − 10 см = 40 см = 400 мм.
Следовательно, перепад составляет 400 мм рт. ст., а не 40 мм рт. ст.: В — 5.
При том же перепаде давлений после замены жидкости:
Δh = ⟦|Δp|¦ρg⟧.
Вода менее плотная, чем ртуть, поэтому для уравновешивания того же перепада нужен более высокий столб: Г — 7. Сравниваем при сохранённом перепаде и достаточно длинных трубках.
Проверка: произведение ρΔh должно сохраниться; при уменьшении плотности высота увеличивается. Последовательность А, Б, В, Г: ${ans}.`,['Прибор измеряет разность давлений','Δh = 40 см = 400 мм',above?'Давление газа больше атмосферного':'Давление газа меньше атмосферного','Вода менее плотная → перепад уровней больше','Ответ: '+ans]);
for(const [id,wood,ans] of [['598FB6',true,'5723'],['150624',false,'6714']])add(id,'Шарик в полном сосуде на весах',ans,`Сосуд наполнен до края; вода, вытесненная шариком, выливается и не остаётся на чашке весов. Плотность ${wood?'сосны меньше':'меди больше'} плотности воды, поэтому шарик ${wood?'плавает с частичным погружением':'тонет и опускается на дно'}: А — ${wood?'5':'6'}. Вытесненная вода выливается: Б — 7.
Работаем в системе Земли, Oy направим вверх. На шарик действуют тяжесть mg вниз и сила Архимеда F_А вверх${wood?'':'; при контакте с дном добавляется нормальная реакция N вверх'}. ${wood?'Для плавающего шарика равновесие даёт F_А − mg = 0.':'После установления на дне равновесие даёт N + F_А − mg = 0.'}
Закон Архимеда:
F_А = ρ_в · gV_погр = m_выт · g.
${wood?'Поэтому вес вытесненной воды равен весу шарика, m_выт = m: Г — 3.':'При полном погружении m_выт = ρ_в · V, а масса шарика m = ρ_меди · V. Следовательно, m_выт < m: вес вытесненной воды меньше веса шарика, Г — 4.'}
Изменение массы на стороне сосуда:
ΔM = m − m_выт.
${wood?'ΔM = 0, поэтому равновесие весов не нарушается: В — 2.':'ΔM > 0, поэтому сторона сосуда становится тяжелее и равновесие нарушается: В — 1.'}
Проверка: сравниваем полную систему «сосуд, оставшаяся вода, шарик». Внутренние силы между её частями не прибавляются второй раз к суммарному весу. Ответ: ${ans}.`,[wood?'Сосновый шарик плавает':'Медный шарик тонет','Часть воды выливается',wood?'m_выт = m → равновесие сохраняется':'m_выт < m → сторона сосуда тяжелее','Ответ: '+ans]);
for(const [id,wood] of [['A6BDC0',true],['17D93A',false]])add(id,'Погружение тела в полный сосуд','33',`Сосуд первоначально заполнен до края. После погружения ${wood?'деревянного кубика':'стального шара'} часть воды выливается, но её поверхность остаётся на прежней высоте — у края сосуда. Сравниваем установившиеся состояния.
Система отсчёта связана с Землёй, Oy направим вверх. Масса тела и g сохраняются, поэтому сила тяжести F_тяж = mg не изменяется — цифра 3. Появление выталкивающей силы не означает уменьшения самой силы тяжести.
${wood?'На плавающий кубик действуют mg вниз и F_А вверх; равновесие даёт F_А − mg = 0.':'На шар, лежащий на дне, действуют mg вниз, сила Архимеда F_А и реакция N вверх. Равновесие: N + F_А − mg = 0. Сила контакта шара с дном — отдельная нагрузка.'}
Гидростатическое давление воды определяется формулой:
p = ρ_в · gh.
Плотность воды и высота h не изменились, следовательно, ${wood?'сила давления воды F = pS при той же площади S':'давление воды на дно'} не меняется — цифра 3.
Проверка: важно различать давление воды, силу контакта тела с дном и силу тяжести тела. Перелив удерживает h постоянной; без перелива уровень мог бы вырасти. В порядке столбцов ответ: 33.`,['Вода переливается через край: h = const','Масса тела постоянна: mg = const','Давление воды: p = ρgh = const','Ответ: 33']);
for(const [id,ratio,ans] of [['04BD3F',2,'4,8'],['F20383',0.5,'2']])add(id,'Сила Архимеда и объёмы шаров',ans,`Оба шара полностью погружены в одну и ту же воду. В школьной модели плотность воды постоянна; глубины отсчитываются от её поверхности. Сила Архимеда направлена вертикально вверх и возникает из-за того, что давление на нижнюю часть тела больше, чем на верхнюю.
Для каждого полностью погружённого шара:
F_А₁ = ρ_в · gV₁;
F_А₂ = ρ_в · gV₂.
При делении уравнений одинаковые ρ_в и g сокращаются:
⟦F_А₁¦F_А₂⟧ = ⟦V₁¦V₂⟧.
${ratio===2?'По условию V₁ = 2V₂, а F_А₂ = 2,4 Н. Сначала выразим искомую силу:\nF_А₁ = 2F_А₂.\nПодстановка:\nF_А₁ = 2 · 2,4 Н = 4,8 Н.':'По условию V₁ = 0,5V₂. Следовательно, F_А₁ = 0,5F_А₂. Искомое число, во сколько раз первая сила меньше второй:\n⟦F_А₂¦F_А₁⟧ = ⟦V₂¦V₁⟧ = 2.'}
Указанные глубины не дают дополнительного множителя: с глубиной растёт давление со всех сторон, а его разность на высоте тела определяется вытесненным объёмом.
Проверка: ${ratio===2?'4,8 Н · (2,4 Н)⁻¹ = 2, что совпадает с отношением объёмов':'уменьшение объёма вдвое уменьшает вытесненную массу воды и выталкивающую силу вдвое'}. Ответ: ${ans}${ratio===2?' Н':' раза'}.`,['Полное погружение: F_А = ρ_в · gV',ratio===2?'V₁ = 2V₂ → F_А₁ = 2F_А₂':'V₂ = 2V₁ → F_А₂ = 2F_А₁','Разная глубина не меняет это отношение','Ответ: '+ans]);
add('A57C8D','Шарик в дистиллированной и морской воде','12',`Сплошной стальной шарик полностью погружают сначала в дистиллированную, затем в морскую воду. Его масса m и объём V сохраняются. Морская вода плотнее дистиллированной из-за растворённых солей.
Система отсчёта связана с Землёй; ось Oy направим вверх. На неподвижный шарик действуют mg вниз, выталкивающая сила F_А вверх и сила упругости нити T вверх. Проекция условия равновесия:
T + F_А − mg = 0.
Закон Архимеда и выражение для натяжения:
F_А = ρ_ж · gV;
T = mg − ρ_ж · gV.
При переходе к более плотной морской воде F_А увеличивается — цифра 1. Сила тяжести остаётся прежней, поэтому необходимое натяжение нити уменьшается — цифра 2.
Проверка: для двух жидкостей можно вычесть уравнения равновесия:
T₂ − T₁ = −(F_А₂ − F_А₁).
При положительном увеличении выталкивающей силы изменение натяжения отрицательно. Стальной шарик тяжелее вытесняемой воды, поэтому нить по-прежнему натянута. Ответ: 12.`,['ρ_морской > ρ_дистиллированной','F_А = ρ_ж · gV возрастает','T + F_А = mg → T уменьшается','Ответ: 12']);
add('EF977E','Линейка под газетным листом','4',`Опыт показывает действие атмосферного давления — вариант 4. Рассматриваем линейку и газету относительно неподвижного стола. При попытке быстро поднять лежащую под газетой часть линейки вместе с ней должен приподняться большой участок листа.
Воздух не успевает быстро проникнуть под плотно разглаженную газету. Под приподнимаемым участком давление p_низ становится меньше атмосферного p_атм над газетой. На этот участок действуют сила давления воздуха сверху вниз, сила давления снизу вверх, собственная тяжесть и контактная сила линейки. Если ось Oy направить вверх, результирующая именно сил давления:
F_y = p_низ · S − p_атм · S = −(p_атм − p_низ)S.
Она направлена вниз. Даже умеренная разность давлений на большой площади создаёт значительную удерживающую силу и момент относительно края стола. Поэтому резкий удар может сломать линейку раньше, чем она поднимет лист.
Проверка: если воздух свободно проходит под газетой, давления почти выравниваются и прижим ослабевает. В опыте существенна разность давлений, а не только небольшой вес газетного листа. Ответ: 4.`,['Под разглаженный лист воздух поступает не сразу','p_низ < p_атм при быстром подъёме','F_прижим = (p_атм − p_низ)S','Ответ: атмосферное давление, 4']);
add('D6291E','Почему вода не вытекает из закрытой бутылки','4',`Опыт выявляет действие атмосферного давления — вариант 4. После герметичного закрывания крышки воздух сверху больше не поступает в бутылку. Если небольшое количество воды ещё выходит, оставшийся над водой газ расширяется и его давление уменьшается.
Рассматриваем установившееся состояние в системе Земли. Пусть h — глубина бокового отверстия ниже поверхности воды, p_внутр — давление газа над водой, p_атм — давление воздуха снаружи. Давление воды у отверстия:
p_отв = p_внутр + ρgh.
Истечение прекращается, когда давления по обе стороны отверстия уравновешиваются:
p_внутр + ρgh = p_атм;
p_внутр = p_атм − ρgh.
Снаружи воздух давит внутрь отверстия и удерживает воду. При открытой крышке p_внутр = p_атм, поэтому внутри отверстия давление больше наружного на ρgh и вода вытекает.
Проверка: вновь открытая крышка выравнивает давление над водой с атмосферным, после чего истечение возобновляется. Гидростатическое давление и тяжесть воды не исчезают; остановку объясняет понижение внутреннего давления при закрытой крышке. Ответ: 4.`,['Крышка закрыта → воздух не поступает','p_внутр уменьшается','У отверстия: p_внутр + ρgh = p_атм','Ответ: 4']);
add('B576D7','Бумага удерживает воду в перевёрнутом стакане','3',`Вода удерживается благодаря действию атмосферного давления — вариант 3. Снаружи на бумагу давит окружающий воздух. Внутри закрытого бумагой перевёрнутого стакана не устанавливается свободное сообщение с атмосферой; малое смещение воды создаёт пониженное давление в верхней области. Там могут быть разреженный воздух и водяной пар; считать давление обязательно равным нулю не требуется.
Работаем в системе Земли, Oy направим вверх. На бумагу действуют давление наружного воздуха вверх, давление воды изнутри вниз и её собственная тяжесть вниз. Давление воды у бумаги:
p_вода = p_верх + ρgh.
При герметичном контакте с краем стакана разность давлений может удерживать бумагу и столб воды. Для лёгкого листка основное сравнение сил:
F_снизу = p_атм · S;
F_сверху = (p_верх + ρgh)S.
Пониженное p_верх позволяет наружному давлению компенсировать нагрузку. В равновесии учитывается также контакт бумаги с краем стакана.
Проверка: если впустить воздух внутрь сверху, p_верх станет атмосферным; добавка ρgh больше не будет компенсирована, и вода начнёт выливаться. Ответ: 3.`,['Снаружи бумагу поддерживает воздух','Внутри над водой давление понижено','Давление воды у бумаги: p_верх + ρgh','Ответ: действие атмосферного давления, 3']);
for(const [id,choice] of [['A56655',false],['964A65',true]])add(id,'Предельная высота всасывания воды','3',`Рассматривается всасывающий поршневой насос: при подъёме поршня давление над водой в трубке уменьшается, а атмосферное давление на свободную поверхность водоёма поднимает воду в трубку. Это предел всасывания за поршнем, а не высота нагнетания воды насосом, установленным внизу.
В системе Земли для покоящегося столба высоты h:
p_атм = p_п + ρgh,
где p_п — давление под поршнем.
Отсюда:
h = ⟦p_атм − p_п¦ρg⟧.
Максимальная идеальная высота получается при очень малом давлении под поршнем:
h_макс ≈ ⟦p_атм¦ρg⟧.
При школьных значениях p_атм ≈ 100 000 Па, ρ = 1000 кг·м⁻³, g = 10 Н·кг⁻¹:
h_макс ≈ ⟦100 000 Па¦1000 кг·м⁻³ · 10 Н·кг⁻¹⟧ = 10 м.
${choice?'Пятиэтажное здание имеет высоту примерно 5 · 3 м = 15 м. Это больше предела около 10 м, поэтому всасыванием с уровня земли поднять воду на такую высоту нельзя. Правильный вариант 3.':'При заданной жидкости точное значение предела прежде всего определяется атмосферным давлением — вариант 3. Реальная высота также зависит от температуры воды и потерь; увеличение площади поршня не устраняет атмосферный предел.'}
Проверка: давление столба воды высотой 10 м равно 1000 · 10 · 10 Па = 100 000 Па, то есть принятому атмосферному. Ответ: 3.`,['Воду поднимает атмосферное давление','h_макс ≈ p_атм · (ρg)⁻¹ ≈ 10 м',choice?'15 м > 10 м: всасыванием нельзя':'Площадь поршня не меняет этот предел','Ответ: 3']);
add('7F55DC','Выталкивающая сила в воздухе','4',`Речь идёт о выталкивающей силе воздуха — вариант 4. Закон Архимеда действует и в газах. На тело объёма V со стороны воздуха действует сила F_А = ρ_возд · gV, направленная вверх.
Работаем в системе Земли, Oy направим вверх. На каждое тело действуют тяжесть mg вниз, реакция чашки N вверх и сила Архимеда вверх. Равновесие:
N + F_А − mg = 0;
N = mg − ρ_возд · gV.
Весы сравнивают силы, переданные чашкам, то есть N, а не непосредственно mg. Для уравновешенных тел при равных плечах:
m_пробки · g − ρ_возд · gV_пробки = m_меди · g − ρ_возд · gV_меди.
Объём пробки больше, следовательно:
m_пробки − m_меди = ρ_возд · (V_пробки − V_меди) > 0.
Большая выталкивающая сила на пробку скрывает небольшое превышение её массы. Поэтому истинная масса медной пластинки меньше.
Проверка: в вакууме обе силы Архимеда исчезли бы; при неизменных массах пробка перевесила бы. Воздушное сопротивление здесь не объясняет результат, поскольку тела неподвижны. Ответ: 4.`,['Воздух тоже создаёт силу Архимеда','N = mg − ρ_возд · gV','Большой объём пробки → большая F_А','Истинная масса пробки немного больше','Ответ: 4']);
const experimentIntro=`Нужно выбрать выводы, подтверждённые именно показанными опытами. Физически правильная зависимость не является результатом этих опытов, если соответствующая величина в них не менялась. Наблюдаем отклонение плёнки или связанной с ней стрелки; при одинаковых плёнках большее отклонение означает большую силу давления.`;
for(const [id,salt,ans] of [['4CC94F',true,'12'],['BD9C63',false,'14']])add(id,'Выводы из опыта с резиновым дном',ans,`${experimentIntro}
В исходных рисунках ${salt?'в одну и ту же трубку налиты равные объёмы воды и раствора соли. Высоты столбов одинаковы, но прогиб плёнки у солевого раствора больше':'в одну и ту же трубку налиты разные объёмы одной и той же воды. Более высокий столб сильнее прогибает плёнку'}. Система отсчёта связана со столом.
1) Подтверждается: плёнка прогибается, значит жидкость действует на дно силой давления.
2) ${salt?'Подтверждается: при той же геометрии и высоте замена воды раствором меняет давление.':'Не проверено: в обоих опытах используется вода, род жидкости не меняется.'}
3) Не проверено: форму сосуда не меняли.
4) ${salt?'Не проверено: высота столба в этих двух опытах одинакова.':'Подтверждается: при увеличении высоты столба воды прогиб возрастает.'}
5) Не проверено: нет измерений по разным направлениям в одной точке жидкости.
Проверка: закон p = ρgh согласуется с наблюдением. В этих опытах изменяется ${salt?'плотность ρ':'высота h'}, а остальные множители сохраняются; сила на дно F = pS изменяется вместе с давлением. Ответ: ${ans}.`,[salt?'Одинаковая высота; разные жидкости':'Одна жидкость; разная высота','Прогиб показывает действие давления',salt?'Подтверждены пункты 1 и 2':'Подтверждены пункты 1 и 4','Ответ: '+ans]);
add('9A05AE','Гидростатический парадокс в опыте Паскаля','25',`${experimentIntro}
В трёх опытах одна и та же вода налита до одинаковой высоты, площади дна равны. Меняется только форма сосудов. На исходном рисунке стрелки отклонены одинаково.
1) Зависимость от высоты этими опытами не проверена: высота во всех трёх сосудах одна и та же.
2) Подтверждается: одинаковые показания означают одинаковые силы давления воды на дно.
3) Зависимость от плотности не проверена: везде используется вода.
4) Зависимость от площади не проверена: площади дна одинаковы.
5) Подтверждается: при изменении формы и сохранении высоты, плотности и площади дна сила не изменилась.
Проверка: для покоящейся воды в системе Земли p = ρgh и F = pS, поэтому F = ρghS. Все множители одинаковы, форма в выражение не входит. Разные массы воды не создают противоречия: на воду действуют также стенки, вертикальные составляющие сил которых могут отличаться. Ответ: 25.`,['Одинаковые ρ, h и S','Форма сосудов различна','Все три стрелки отклонены одинаково','F = ρghS одинакова','Ответ: 25']);
for(const [id,maximum,ans] of [['8FDB90',true,'12'],['52DFED',false,'13']])add(id,'Опыты Паскаля: высота и род жидкости',ans,`${experimentIntro}
В опытах 1 и 2 используется жидкость 1: во втором её уровень ниже, а стрелка отклоняется меньше. В опытах 1 и 3 высота одинакова, но жидкость заменена; в опыте 3 стрелка отклоняется сильнее. Площади дна и форма сосуда во всех опытах одинаковы.
1) Подтверждается сравнением опытов 1 и 2: большему столбу соответствует большая сила давления.
2) ${maximum?'Подтверждается рисунком: максимальное отклонение стрелки и максимальная сила наблюдаются в опыте 3.':'Опровергается рисунком: отклонения различны, силы во всех трёх опытах не равны.'}
3) ${maximum?'Утверждение о независимости от рода жидкости опровергается опытами 1 и 3.':'Зависимость от рода жидкости подтверждается опытами 1 и 3 при одинаковой высоте.'}
4) ${maximum?'Независимость от формы не исследована: форма не менялась.':'Зависимость от площади не исследована: площадь не менялась.'}
5) ${maximum?'Зависимость от площади не исследована: площадь не менялась.':'Независимость от формы не исследована: форма не менялась.'}
Проверка: F = ρghS. Уменьшение h при одной жидкости уменьшает силу. При равных h и S большее показание опыта 3 означает большую плотность жидкости 2. В исходном порядке утверждений ответ: ${ans}.`,['Опыты 1 и 2: меняется высота','Опыты 1 и 3: меняется жидкость','По стрелкам: F₃ > F₁ > F₂','Ответ: '+ans]);
add('7332F9','Барометр во дворе и на пятом этаже','Во дворе давление больше.',`Показания будут различными: барометр во дворе покажет большее атмосферное давление, чем барометр на пятом этаже. Сравниваем одновременные измерения; школьное помещение сообщается с наружным воздухом и не является герметичной камерой с искусственным давлением.
Рассмотрим в системе Земли вертикальный столб воздуха между уровнями двух барометров, ось Oy направим вверх. На него действуют сила давления нижних слоёв вверх, сила давления верхних слоёв вниз и собственная тяжесть вниз. Равновесие:
p_низ · S − p_верх · S − m_возд · g = 0.
Следовательно:
p_низ − p_верх = ⟦m_возд · g¦S⟧ > 0.
При небольшой разности высот и приблизительно постоянной плотности воздуха это можно записать как p_низ − p_верх ≈ ρ_возд · gΔh. Чем выше точка наблюдения, тем меньший столб воздуха находится над ней и тем ниже давление.
Проверка: при одинаковой высоте и прочих одинаковых условиях разность была бы близка к нулю. Здесь пятый этаж выше двора, поэтому направление разности однозначно, хотя она невелика.`,['Двор расположен ниже кабинета','Нижние слои поддерживают столб воздуха','p_низ − p_верх ≈ ρ_возд · gΔh > 0','Ответ: барометр во дворе покажет больше']);
for(const [id,warm,energy] of [['8C8E0D',true,true],['CDD3A6',false,true],['DDD590',false,false],['C9766A',true,false]])add(id,'Колба с газом и жидкостный манометр',energy?(warm?'Внутренняя энергия увеличилась.':'Внутренняя энергия уменьшилась.'):(warm?'Температура воды выше температуры окружающей среды.':'Температура воды ниже температуры окружающей среды.'),`До помещения колбы в воду уровни жидкости в коленах одинаковы, поэтому давление газа равно атмосферному. Газ находился в тепловом равновесии с окружающей средой.
На втором исходном рисунке уровень в левом колене, соединённом с колбой, ${warm?'ниже':'выше'} уровня в правом, открытом колене. Следовательно, давление газа стало ${warm?'выше':'ниже'} атмосферного. В системе Земли для равновесия манометрической жидкости:
p_газ = p_атм ${warm?'+':'−'} ρ_м · gΔh,
где Δh — положительная разность уровней, ρ_м — плотность жидкости манометра.
Колба жёсткая, количество газа сохраняется; изменение его объёма в узкой соединительной трубке считаем пренебрежимо малым. Тогда повышение давления означает нагревание, а понижение — охлаждение. Количественно в модели идеального газа:
⟦p₂¦p₁⟧ = ⟦T₂¦T₁⟧ при V = const.
${energy?`Температура газа ${warm?'повысилась':'понизилась'}, средняя энергия теплового движения молекул ${warm?'возросла':'уменьшилась'}, значит внутренняя энергия газа ${warm?'увеличилась':'уменьшилась'}. При постоянном объёме работа газа пренебрежимо мала, изменение энергии связано с теплообменом с водой.`:`Вода ${warm?'нагрела':'охладила'} газ относительно его первоначального состояния. Поэтому температура воды ${warm?'выше':'ниже'} температуры окружающей среды; после установления теплового равновесия газ приобретает температуру воды.`}
Проверка: ${warm?'при нагревании газ сильнее давит на жидкость и опускает её со своей стороны':'при охлаждении газ слабее давит на жидкость, и атмосферный воздух поднимает её со стороны колбы'}. Это совпадает с исходным рисунком.`,[warm?'Уровень слева ниже → давление газа выросло':'Уровень слева выше → давление газа упало','Масса и объём газа практически постоянны',warm?'Газ нагрелся; внутренняя энергия выросла':'Газ охладился; внутренняя энергия уменьшилась']);
for(const [id,salt] of [['8B14B3',true],['8D5935',false]])add(id,'Сила давления камня на дно',salt?'Уменьшится.':'Не изменится.',`Камень полностью погружён в воду и касается дна отдельными участками; вода проникает под него. Случай герметичного прилегания всей нижней поверхности здесь не рассматривается.
Работаем в системе Земли; Oy направим вверх. На камень действуют mg вниз, сила Архимеда F_А вверх и нормальная реакция дна N вверх. Равновесие:
N + F_А − mg = 0;
N = mg − F_А.
По третьему закону Ньютона сила давления камня на дно равна N по модулю и направлена вниз. Для полностью погружённого камня:
F_А = ρ_в · gV.
${salt?'После растворения соли плотность жидкости возрастает. При неизменных объёме камня и g выталкивающая сила увеличивается, поэтому N уменьшается. Сама сила тяжести mg не меняется.':'Керосин располагается сверху и не смешивается с водой. Камень остаётся целиком в воде; плотность воды и вытесненный камнем объём не меняются. Столб керосина добавляет ко всем давлениям в воде одну и ту же величину ρ_кер · gh_кер. Эта добавка не изменяет результирующую сил давления на замкнутую поверхность камня, поэтому F_А и N сохраняются.'}
Проверка: ${salt?'ΔN = −gV · Δρ < 0; увеличение плотности действительно уменьшает нагрузку камня на дно':'большее абсолютное давление на глубине не означает большую силу Архимеда; её определяет разность давлений и плотность окружающей именно камень воды'}. Ответ: сила давления ${salt?'уменьшится':'не изменится'}.`,['N + F_А = mg','F_А = ρ_в · gV',salt?'Раствор соли плотнее → F_А больше':'Керосин сверху не меняет плотность воды',salt?'Ответ: сила на дно уменьшится':'Ответ: сила на дно не изменится']);
add('A8561C','Зачем под гайку кладут шайбу','Сила давления не изменится.',`При одинаковом усилии затяжки сила давления на скрепляемую деталь не изменится. Шайба распределяет ту же силу по большей площади, поэтому уменьшается давление. В условии спрашивается именно сила, а не давление.
Работаем в системе детали; ось направим вдоль болта. На неподвижную шайбу действуют сила гайки F в сторону детали и противоположная реакция детали N. Весом шайбы по сравнению с силой затяжки пренебрегаем. В проекции условие равновесия:
F − N = 0;
N = F.
Следовательно, шайба передаёт детали ту же силу, которую получает от гайки. Среднее давление при площади контакта S:
p = ⟦F¦S⟧.
Широкое кольцо увеличивает площадь контакта с деталью, поэтому при неизменной F давление становится меньше, деталь слабее сминается.
Проверка: если площадь опоры увеличить вдвое, среднее давление уменьшится вдвое, но произведение pS останется прежним и равным F. Без сравнения при одинаковой затяжке сама геометрия шайбы не задаёт новое усилие. Ответ: сила давления не изменится.`,['Та же сила затяжки F','Шайба увеличивает площадь опоры S','pS = F: давление уменьшается','Ответ: сила сохраняется']);
for(const [id,increase] of [['0CC527',true],['396256',false]])add(id,'Вода в запаянной сверху трубке',increase?'Уровень воды в трубке повысится.':'Уровень воды в трубке понизится.',`Уровень воды в трубке ${increase?'повысится':'понизится'}. В трубке заперт воздух: через запаянный верх он не выходит. Снаружи атмосферное давление передаётся воде через свободную поверхность.
Работаем в системе Земли; положение трубки фиксировано, ось Oy направим вверх. Обозначим H глубину её открытого конца относительно наружной поверхности, x — высоту воды, вошедшей внутрь от нижнего конца. Для одинакового горизонтального уровня у входа давления должны совпадать:
p_газ + ρgx = p_атм + ρgH;
p_газ = p_атм + ρg(H − x).
Сразу после ${increase?'увеличения':'уменьшения'} p_атм давление воды снаружи у входа ${increase?'становится больше прежнего внутреннего, и вода входит в трубку':'становится меньше прежнего внутреннего, и запертый газ вытесняет часть воды'}. Объём запертого газа ${increase?'уменьшается, газ сжимается':'увеличивается, газ расширяется'} до нового равновесия.
Проверка: при медленном изменении и постоянной температуре p_газ · S(L − x) = const. Рост x повышает p_газ из-за сжатия и одновременно уменьшает величину ρg(H − x), поэтому ${increase?'увеличившееся':'уменьшившееся'} атмосферное давление согласуется с ${increase?'большим':'меньшим'} x. Здесь L — длина трубки, S — её сечение.`,['Запертый газ меняет объём','p_газ + ρgx = p_атм + ρgH',increase?'Атмосферное давление растёт → вода входит':'Атмосферное давление падает → вода выходит',increase?'Ответ: уровень повысится':'Ответ: уровень понизится']);
add('5C7C29','Открывание перегородки в сообщающихся сосудах','Вода переливаться не будет.',`После открытия перегородки направленного переливания воды из одного сосуда в другой не будет. На исходном рисунке свободные поверхности находятся на одной горизонтали; оба сосуда открыты в атмосферу и заполнены одной жидкостью.
${hydro}
Точки по разные стороны перегородки на одной высоте имеют одинаковую глубину h относительно свободной поверхности. Поэтому:
p_слева = p_атм + ρgh;
p_справа = p_атм + ρgh;
p_слева = p_справа.
Если выделить маленький горизонтальный объём воды у открывшегося прохода, силы давления слева и справа равны и противоположны. Их горизонтальная сумма равна нулю; причины для потока в одну из сторон нет.
Проверка: в широком сосуде воды больше, но давление у прохода определяется высотой столба, а не общей массой жидкости в сосуде. Если бы уровни различались, вода потекла бы с более высокого уровня к более низкому. Здесь уровни уже равны.`,['Одна жидкость; поверхности на одной высоте','Глубины у перегородки одинаковы','p_слева = p_справа','Ответ: направленного переливания нет']);
add('0D4A51','Пробка в колбе под воздушным колоколом','При достаточной откачке пробка вылетит из колбы.',`При достаточном понижении наружного давления пробка вылетит из колбы. Пока пробка закрывает горлышко, воздух внутри колбы не откачивается вместе с воздухом под колоколом.
Рассматриваем колбу относительно стола; ось Oy направим вдоль горлышка наружу, для вертикального горлышка вверх. На пробку действуют сила внутреннего давления p_внутр · S наружу, сила наружного давления p_снаружи · S внутрь, тяжесть вниз и удерживающая сила контакта с горлышком. До движения реакция и трение удерживают пробку.
Результирующая сил давления:
F_давл = (p_внутр − p_снаружи)S.
При откачке p_снаружи уменьшается, а p_внутр до смещения пробки остаётся приблизительно прежним. Поэтому F_давл растёт. Когда она превышает тяжесть и максимально возможное удерживающее действие горлышка, равновесие становится невозможным, пробка движется наружу.
Проверка: важна разность давлений; сама вода не должна для этого закипать. При совсем малой откачке плотно сидящая пробка может ещё удерживаться трением, поэтому вылет связываем с достаточным перепадом, а не с любым бесконечно малым изменением давления.`,['Воздух из закрытой колбы не откачивается','p_снаружи уменьшается','F_давл = (p_внутр − p_снаружи)S растёт','При достаточном перепаде пробка вылетит']);
for(const [id,pumpIn] of [['ED935C',true],['D753E1',false]])add(id,'Надутый шарик под колпаком',pumpIn?'Объём шарика уменьшится.':'Объём шарика увеличится.',`Объём шарика ${pumpIn?'уменьшится':'увеличится'}. Шарик завязан, поэтому количество воздуха внутри него сохраняется; накачивание или откачивание меняет прежде всего давление воздуха снаружи его оболочки.
Работаем в системе установки. На каждый малый участок оболочки газ внутри действует наружу, газ под колпаком — внутрь, а натяжение резины стремится стянуть оболочку. Равновесие требует баланса этих действий. Из-за упругости резины внутреннее и внешнее давления не обязаны быть строго равными.
При ${pumpIn?'накачивании воздуха под колпак наружное давление повышается. Внешнее сжатие усиливается, оболочка смещается внутрь, газ в шарике сжимается':'откачивании воздуха из-под колпака наружное давление понижается. Внутренний газ получает возможность растянуть оболочку сильнее и расширяется'} до нового равновесия.
Для медленного изменения при примерно постоянной температуре газа:
p_внутр · V = const.
${pumpIn?'Уменьшение V повышает внутреннее давление, противодействуя дальнейшему сжатию.':'Увеличение V понижает внутреннее давление, противодействуя дальнейшему расширению.'} Одновременно меняется натяжение резины; ответ относится к обычному устойчивому состоянию надутого шарика.
Проверка: число молекул внутри остаётся тем же, ${pumpIn?'плотность газа увеличивается':'плотность газа уменьшается'}. Изменение объёма не требует выхода или поступления воздуха через узел.`,['Шарик завязан: масса газа сохраняется',pumpIn?'Наружное давление увеличивается':'Наружное давление уменьшается','Учитываем также натяжение резины',pumpIn?'Ответ: объём уменьшится':'Ответ: объём увеличится']);
add('38569C','Кусок дерева в сосуде без перелива','Давление на дно увеличилось.',`Давление воды на дно увеличилось. После помещения дерева часть его объёма оказывается под водой и вытесняет воду вверх. По условию вода не выливалась, поэтому её свободная поверхность стала выше.
${hydro}
Плотность воды, g и положение дна не меняются. Если уровень поднялся на Δh > 0, изменение гидростатического давления:
Δp = ρgΔh > 0.
Для свободно плавающего куска дерева в системе Земли на него действуют тяжесть mg вниз и сила Архимеда вверх. Равновесие даёт F_А − mg = 0, откуда V_погр = m · ρ⁻¹ > 0. Поэтому подъём воды имеет физическую причину — ненулевой вытесненный объём.
Проверка: в цилиндрическом сосуде площади сечения S подъём Δh = V_погр · S⁻¹. Тогда добавочная сила воды на дно равна ΔpS = ρgV_погр = mg. Для сосуда другой формы численное соотношение может отличаться из-за сил стенок, но рост уровня и давления сохраняется.`,['Дерево вытесняет часть воды','Перелива нет → уровень повышается','Δp = ρgΔh > 0','Ответ: давление увеличилось']);
add('341998','Бумага под верёвкой уменьшает давление','Да, боль уменьшится.',`Боль уменьшится: сложенная бумага или плотная ткань распределяет нагрузку по большей площади пальцев. Масса книг и требуемая сила поддержки при этом практически не меняются.
Рассматриваем неподвижную стопку в системе Земли, Oy направляем вверх. На стопку действуют тяжесть Mg вниз и суммарная вертикальная сила поддержки верёвкой F вверх. Условие равновесия:
F − Mg = 0;
F = Mg.
Через верёвку эта нагрузка передаётся руке. Тонкая верёвка соприкасается с пальцами на небольшой площади S₁, поэтому среднее давление велико. Прокладка увеличивает площадь передачи силы до S₂ > S₁:
p₁ = ⟦F¦S₁⟧;
p₂ = ⟦F¦S₂⟧;
⟦p₂¦p₁⟧ = ⟦S₁¦S₂⟧ < 1.
При меньшем давлении ткани пальцев сдавливаются слабее, поэтому боль уменьшается. Речь идёт о распределении той же нагрузки, а не об уменьшении веса книг.
Проверка: если площадь контакта увеличить в три раза, среднее давление уменьшится втрое, но полная сила F останется прежней. Ответ: да, уменьшится.`,['Вес книг и сила поддержки те же','Бумага увеличивает площадь контакта','p = F · S⁻¹ уменьшается','Ответ: боль уменьшится']);
add('204C34','Вода и неизвестная жидкость в U-трубке','Плотность неизвестной жидкости меньше плотности воды.',`Плотность неизвестной жидкости меньше плотности воды. На исходном рисунке неизвестная жидкость находится сверху в правом колене; для сравнения выбираем горизонталь через её нижнюю границу с водой.
${hydro}
Слева над этой горизонталью находится столб воды высотой h_в, справа — столб неизвестной жидкости высотой h_ж. Обе свободные поверхности открыты атмосфере. На выбранной горизонтали в соединённой воде давления одинаковы:
p_атм + ρ_в · gh_в = p_атм + ρ_ж · gh_ж;
ρ_в · h_в = ρ_ж · h_ж.
На рисунке верхняя поверхность неизвестной жидкости выше левой поверхности воды, поэтому при общей нижней горизонтали h_ж > h_в. Отсюда:
⟦ρ_ж¦ρ_в⟧ = ⟦h_в¦h_ж⟧ < 1.
Проверка: более высокий столб менее плотной жидкости создаёт то же давление, что более низкий столб воды. Сравнивать высоты от дна изгиба трубки было бы неверно: общий нижний участок воды не входит в разность давлений.`,['Высоты отсчитываем от границы жидкостей','h_ж > h_в','ρ_ж · h_ж = ρ_в · h_в','Ответ: неизвестная жидкость менее плотная']);
add('A4B7E8','Почему диск на дне банки не заменяет дно прибора','Нет, предложенный опыт не измеряет искомую силу давления.',`Надёжно провести запланированное исследование таким способом не удалось. Алюминиевый диск просто положен на целое дно банки и не закрывает специальное отверстие герметично. Вода может проникать под диск, поэтому динамометр измеряет не силу давления только на его верхнюю поверхность.
Работаем в системе Земли, Oy направим вверх. На погружённый диск действуют mg вниз, натяжение нити T вверх, результирующая сил воды F_А вверх, а до отрыва ещё и реакция дна N вверх. Равновесие:
T + F_А + N − mg = 0.
В момент плавного отрыва N обращается в нуль. Если вода свободно попадает под полностью погружённый диск:
T = mg − F_А;
F_А = ρ_в · gV.
При постоянных m, V и плотности воды эта величина не зависит от глубины. Увеличение уровня увеличивает давление и сверху, и снизу; основная общая добавка взаимно компенсируется.
Проверка: для исследования давления нужен герметичный чувствительный элемент, на противоположной стороне которого давление известно, как в приборе с отверстием. При случайном плотном прилегании диска результат зависел бы ещё от герметичности и прилипания, не заданных условием. Измерять такую силу отрыва как однозначную силу давления воды на дно нельзя.`,['Вода проникает под просто положенный диск','При отрыве: T + F_А = mg','Полное погружение: F_А = ρ_в · gV','Высота воды не определяет T','Ответ: исследование не удалось']);
add('051105','Динамометр и гидростатический парадокс','Нет.',`Нет, утверждать равенство показания динамометра силе тяжести всей воды нельзя. На рисунке трубка расширяется кверху; круг закрывает её нижнее отверстие AB. Часть вертикальной нагрузки воды воспринимают наклонные стенки, закреплённые в штативе.
Система отсчёта связана со штативом; Oy направим вверх. Обозначим S площадь отверстия AB, h расстояние от AB до уровня CD, m массу воды. Рассмотрим обычную модель: круг лишь удерживает воду и не прижат дополнительно к краю трубки. На лёгкий нижний круг действуют натяжение T вверх, давление наружного воздуха p_атм · S вверх и давление воды (p_атм + ρgh)S вниз. Весом круга пренебрегаем. Условие равновесия:
T + p_атм · S − (p_атм + ρgh)S = 0;
T = ρghS.
Таким образом, атмосферные слагаемые компенсируются. Объяснять отличие T от mg только атмосферным давлением снизу нельзя: атмосфера действует и на свободную поверхность воды.
У расширяющейся трубки каждое горизонтальное сечение выше дна имеет площадь больше S. Поэтому объём налитой воды V больше Sh:
mg = ρVg > ρShg = T.
Для самой воды баланс сил, если использовать избыточные давления относительно атмосферы, имеет вид:
T + R_y − mg = 0.
Здесь R_y > 0 — суммарная вертикальная составляющая сил наклонных стенок на воду. Каждая реакция направлена по нормали к стенке внутрь жидкости и имеет составляющую вверх.
Проверка: у цилиндрической трубки вертикальные стенки не дают такой составляющей, V = Sh и в этой модели T = mg. На исходном рисунке стенки наклонены и трубка расширяется, поэтому T < mg. Если дополнительно прижать круг к краю, возникнет ещё и контактная сила края; такое показание тем более нельзя однозначно считать весом воды.`,['AB — нижнее отверстие; CD — уровень воды','Модель без дополнительного прижатия круга','На круг: T + p_атм · S = (p_атм + ρgh)S','T = ρghS; расширяющаяся трубка: V > Sh','В этой модели T < mg. Ответ: нет']);
add('24DA70','Воздушная струя над листом бумаги','Лист поднимается.',`Лист поднимается. В описанном опыте поток направляют вдоль верхней поверхности листа, а под ним воздух движется заметно медленнее. Согласно приведённому в условии объяснению Бернулли, область более быстрого потока имеет меньшее статическое давление.
Рассматриваем лист в системе Земли, Oy направим вверх. На свободную часть действуют тяжесть вниз, давление воздуха снизу вверх, давление воздуха сверху вниз и упругие силы бумаги у удерживаемого края. Обозначим давления p_низ и p_верх. В школьной модели опыта:
p_низ > p_верх.
Результирующая сил давления на участок площади S направлена вверх:
F_давл = (p_низ − p_верх)S.
При достаточной скорости струи эта добавка меняет баланс сил и моментов: свободный край отклоняется вверх, пока тяжесть и упругость листа не уравновесят новое действие воздуха. Дуть прямо в торец или вниз на лист — другой опыт.
Проверка: прекращение струи устраняет вызванную потоком разность давлений, и бумага возвращается под действием тяжести и упругости. Объяснение относится к показанному направлению обтекания; высокая скорость сама по себе без условий потока не задаёт давление в произвольной точке.`,['Струя идёт над верхней поверхностью','p_верх < p_низ','Разность давлений действует вверх','Ответ: лист поднимается']);
add('89C17C','Струя между подвешенными шариками','Шарики сближаются.',`Шарики сближаются: воздух в быстром потоке между ними имеет пониженное давление по сравнению с воздухом с внешних сторон. Именно такую школьную модель обтекания задаёт текст о законе Бернулли.
Работаем в системе Земли. Для каждого шарика направим локальную ось Ox к другому шарику, Oy вверх. На шарик действуют тяжесть вниз, натяжение нити вдоль неё к подвесу и распределённые силы давления воздуха. Суммарная горизонтальная составляющая давления направлена в область меньшего давления — к промежутку между шариками.
В начале нити почти вертикальны. Их горизонтальные составляющие близки к нулю, а разность сил давления даёт ускорение внутрь промежутка:
m a_x = F_наруж − F_между > 0.
По мере отклонения нитей возникают направленные наружу компоненты натяжения, которые могут уравновесить действие потока. Поэтому речь о сближении под действием воздуха, а не о возникновении особой силы притяжения между материалами шариков.
Проверка: если поток прекратить, разность давлений исчезает и шарики возвращаются ближе к вертикальному положению нитей. Изменение объясняется давлением, без необходимости предполагать электризацию.`,['Между шариками воздух движется быстрее','Давление в промежутке ниже','Силы воздуха направлены к промежутку','Ответ: шарики сближаются']);
add('888147','Воздушный поток у скоростного поезда','Поток воздуха может увлечь человека к поезду и нарушить равновесие.',`Скоростной поезд создаёт сильный воздушный поток рядом с собой. В школьной модели из приведённого текста в узком промежутке между человеком и поездом воздух движется быстрее, чем с другой стороны человека; давление там понижено. Возникает поперечная сила, способная увлечь человека к поезду и нарушить равновесие.
Рассматриваем человека в системе платформы. Ось Ox направим к поезду, Oy — вверх. Действуют тяжесть mg вниз, реакция платформы N вверх, сила трения обуви о платформу и силы давления воздуха. В вертикальном направлении до потери равновесия N примерно равно mg. По горизонтали:
m a_x = F_воздуха − F_тр.
Если трение не удерживает человека, появляется ускорение к поезду. Даже при удержании ног воздушная сила на верхнюю часть тела создаёт опрокидывающий момент и может вывести центр тяжести за площадь опоры.
Проверка: опасность определяется и разностью давлений, и нестационарными порывами; около реального поезда поток неоднороден. Упрощённое объяснение Бернулли показывает причину поперечного воздействия, но не даёт численной силы или безопасного расстояния без дополнительных данных.`,['Быстрый поток рядом с поездом','Пониженное давление в промежутке','Воздушная сила может нарушить равновесие','Опасно приближаться к краю платформы']);
add('18AC77','Глубина и время по таблице условия','Да, согласно таблице допустима.',`Согласно приведённой в задаче таблице работа в течение 2,5 ч на глубине 30 м допустима. В таблице задано давление дополнительно к атмосферному, поэтому для выбора строки вычисляем именно ρgh, не прибавляя атмосферное давление.
В школьном расчёте принимаем плотность воды ρ = 1000 кг·м⁻³, g = 10 Н·кг⁻¹ и 1 атм ≈ 10⁵ Па. Из гидростатического равновесия в системе Земли:
Δp = ρgh.
Подстановка:
Δp = 1000 кг·м⁻³ · 10 Н·кг⁻¹ · 30 м = 300 000 Па ≈ 3 атм.
Значение 3 атм попадает в интервал 2,91–3,2 атм. В соответствующей строке максимальное время равно 2 ч 48 мин.
Переведём оба времени в минуты:
t = 2,5 · 60 мин = 150 мин;
t_доп = 2 · 60 мин + 48 мин = 168 мин.
Проверка: 150 < 168, запас по таблице составляет 18 мин. Полное давление было бы около 4 атм, но выбирать по нему строку этой таблицы неверно. Вывод сделан исключительно по учебной таблице данного условия; она не задаёт самостоятельный план реального погружения.`,['Нужно избыточное давление: Δp = ρgh','30 м → примерно 3 атм сверх атмосферного','Таблица: 2 ч 48 мин = 168 мин','2,5 ч = 150 мин < 168 мин','Ответ по таблице: да']);
for(const [id,temp,boil] of [['E7D3E9',125,true],['7A7175',100,false]])add(id,'Закипит ли вода в гейзерной трубке',boil?'Да, вода закипит.':'Нет, вода не закипит.',`Над рассматриваемой водой после подъёма остаётся столб высотой h = 10 м. Атмосферное давление по первичному условию равно 10⁵ Па. На графике приведена температура кипения как функция полного давления, поэтому учитываем атмосферное и гидростатическое слагаемые.
В системе Земли для столба покоящейся воды:
p = p_атм + ρgh.
Принимаем ρ = 1000 кг·м⁻³ и g = 10 Н·кг⁻¹. Подстановка:
p = 100 000 Па + 1000 кг·м⁻³ · 10 Н·кг⁻¹ · 10 м = 200 000 Па.
В принятом в задаче приближении 1 атм = 10⁵ Па получаем p = 2 атм. По исходному графику этому давлению соответствует температура кипения 120 °C.
Температура воды дана ${temp} °C, поэтому:
${temp} °C ${boil?'>':'<'} 120 °C.
${boil?'Вода перегрета относительно температуры кипения при новом давлении и закипит.':'Температура воды ниже температуры кипения при этом давлении, поэтому она не закипит.'}
Проверка: 100 °C — температура кипения при давлении около 1 атм. На глубине 10 м полное давление вдвое больше, поэтому пользоваться порогом 100 °C нельзя. Исходные 10⁵ Па вместе с добавкой 10⁵ Па действительно дают 2 · 10⁵ Па.`,['h = 10 м; p_атм = 10⁵ Па','p = p_атм + ρgh = 2 · 10⁵ Па','По графику: при 2 атм кипение при 120 °C',boil?'125 °C > 120 °C → закипит':'100 °C < 120 °C → не закипит']);
